<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { createFishApi, deleteFishApi, listFishesApi, updateFishApi } from '../api/fish'
import { listAdminFishApplicationsApi, reviewFishApplicationApi } from '../api/fishApplication'
import { listFishProfileTasksApi, reviewFishProfileTaskApi } from '../api/admin'
import type { FishInfo } from '../types/api'
import type { FishInfoApplication, FishProfileTask } from '../types/business'

const tab=ref('fishes'); const fishes=ref<FishInfo[]>([]); const applications=ref<FishInfoApplication[]>([]); const tasks=ref<FishProfileTask[]>([]); const dialog=ref(false); const editingId=ref<number|null>(null)
const form=reactive({chineseName:'',scientificName:'',category:'',appearance:'',habits:'',habitat:'',distribution:'',protectionLevel:'',coverImageUrl:'',sourceType:'OFFICIAL',sourceDescription:''})
async function load(){fishes.value=(await listFishesApi({page:1,size:100})).data.data.records;applications.value=(await listAdminFishApplicationsApi({page:1,size:50})).data.data.records;tasks.value=(await listFishProfileTasksApi({page:1,size:50})).data.data.records}
function openForm(fish?:FishInfo){editingId.value=fish?.id||null;Object.assign(form,{chineseName:fish?.chineseName||'',scientificName:fish?.scientificName||'',category:fish?.category||'',appearance:fish?.appearance||'',habits:fish?.habits||'',habitat:fish?.habitat||'',distribution:fish?.distribution||'',protectionLevel:fish?.protectionLevel||'',coverImageUrl:fish?.coverImageUrl||'',sourceType:fish?.sourceType||'OFFICIAL',sourceDescription:fish?.sourceDescription||''});dialog.value=true}
async function save(){if(editingId.value)await updateFishApi(editingId.value,form);else await createFishApi(form);ElMessage.success(editingId.value?'鱼类资料已修改':'鱼类资料已新增');dialog.value=false;load()}
async function remove(id:number){await ElMessageBox.confirm('逻辑删除后数据库仍保留记录，但普通查询不会再显示。','删除鱼类资料');await deleteFishApi(id);ElMessage.success('资料已逻辑删除');load()}
async function reviewApplication(id:number,decision:string){const{value}=await ElMessageBox.prompt('填写审核意见','鱼类资料申请审核',{inputValue:decision==='APPROVED'?'资料核实无误':'资料来源或内容需要补充'});await reviewFishApplicationApi(id,decision,value);ElMessage.success('申请已处理');load()}
async function resolveTask(task:FishProfileTask){const{value}=await ElMessageBox.prompt('输入关联鱼类 ID；填写 0 表示忽略','处理未收录物种',{inputPattern:/^\d+$/,inputErrorMessage:'请输入数字 ID'});const fishId=Number(value);await reviewFishProfileTaskApi(task.id,fishId>0?'RESOLVED':'IGNORED',fishId>0?fishId:null,fishId>0?'已关联鱼类资料':'确认忽略');ElMessage.success('待办已处理');load()}
onMounted(load)
</script>
<template><section class="admin-page"><aside class="admin-sidebar"><div class="admin-title"><span class="brand-mark">蓝</span><div><strong>资料管理台</strong><small>FISH ARCHIVE</small></div></div><button :class="{active:tab==='fishes'}" @click="tab='fishes'">鱼类资料</button><button :class="{active:tab==='applications'}" @click="tab='applications'">用户资料申请</button><button :class="{active:tab==='tasks'}" @click="tab='tasks'">识别待办</button><RouterLink to="/admin">返回管理概览</RouterLink></aside><main class="admin-content"><header><div><p>KNOWLEDGE MANAGEMENT</p><h1>{{tab==='fishes'?'鱼类资料库':tab==='applications'?'用户资料申请':'未收录识别待办'}}</h1></div><el-button v-if="tab==='fishes'" type="primary" @click="openForm()">新增鱼类</el-button></header><template v-if="tab==='fishes'"><el-table :data="fishes" stripe><el-table-column prop="id" label="ID" width="65"/><el-table-column prop="chineseName" label="中文名"/><el-table-column prop="scientificName" label="学名" min-width="180"/><el-table-column prop="category" label="分类"/><el-table-column prop="protectionLevel" label="保护等级"/><el-table-column prop="sourceType" label="来源"/><el-table-column label="操作" width="140"><template #default="scope"><el-button link type="primary" @click="openForm(scope.row)">编辑</el-button><el-button link type="danger" @click="remove(scope.row.id)">删除</el-button></template></el-table-column></el-table></template><template v-else-if="tab==='applications'"><el-table :data="applications" stripe><el-table-column prop="applicationType" label="类型"/><el-table-column prop="chineseName" label="鱼类名称"/><el-table-column prop="targetFishId" label="目标 ID"/><el-table-column prop="sourceDescription" label="资料来源" min-width="190"/><el-table-column prop="reason" label="申请原因" min-width="190"/><el-table-column prop="status" label="状态"/><el-table-column label="审核" width="150"><template #default="scope"><template v-if="scope.row.status==='PENDING'"><el-button link type="success" @click="reviewApplication(scope.row.id,'APPROVED')">通过</el-button><el-button link type="danger" @click="reviewApplication(scope.row.id,'REJECTED')">拒绝</el-button></template><span v-else>{{scope.row.reviewComment}}</span></template></el-table-column></el-table></template><template v-else><el-table :data="tasks" stripe><el-table-column prop="id" label="ID"/><el-table-column prop="className" label="识别类别"/><el-table-column prop="detectionResultId" label="识别结果 ID"/><el-table-column prop="status" label="状态"/><el-table-column prop="linkedFishId" label="关联鱼类 ID"/><el-table-column prop="reviewComment" label="处理意见"/><el-table-column label="操作"><template #default="scope"><el-button v-if="scope.row.status==='PENDING'" link type="primary" @click="resolveTask(scope.row)">处理</el-button></template></el-table-column></el-table></template></main><el-dialog v-model="dialog" :title="editingId?'编辑鱼类资料':'新增鱼类资料'" width="min(760px,94vw)"><el-form :model="form" label-position="top"><div class="form-row"><el-form-item label="中文名"><el-input v-model="form.chineseName"/></el-form-item><el-form-item label="学名"><el-input v-model="form.scientificName"/></el-form-item></div><div class="form-row"><el-form-item label="分类"><el-input v-model="form.category"/></el-form-item><el-form-item label="保护等级"><el-input v-model="form.protectionLevel"/></el-form-item></div><el-form-item label="外形特征"><el-input v-model="form.appearance" type="textarea"/></el-form-item><el-form-item label="生活习性"><el-input v-model="form.habits" type="textarea"/></el-form-item><div class="form-row"><el-form-item label="栖息地"><el-input v-model="form.habitat"/></el-form-item><el-form-item label="地理分布"><el-input v-model="form.distribution"/></el-form-item></div><div class="form-row"><el-form-item label="来源类型"><el-input v-model="form.sourceType"/></el-form-item><el-form-item label="封面地址"><el-input v-model="form.coverImageUrl"/></el-form-item></div><el-form-item label="来源说明"><el-input v-model="form.sourceDescription"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存资料</el-button></template></el-dialog></section></template>
